// The widget domain: the validation rules from SPEC.md §5.3 and an in-memory store.
// There is no persistence by design (§4.2) — a restart starts from an empty store.

import { randomUUID } from "node:crypto";

export const NAME_MAX_LENGTH = 64;

export interface Widget {
    /** UUID v4, generated by the server. */
    id: string;
    /** 1..64 characters after trimming. Stored trimmed. */
    name: string;
    /** Integer >= 0. */
    quantity: number;
    /** ISO-8601 UTC timestamp, generated by the server. */
    createdAt: string;
}

/** The only fields a client may supply. Anything else in a request body is ignored. */
export interface WidgetInput {
    name: string;
    quantity: number;
}

export type Validation = { ok: true; value: WidgetInput } | { ok: false; details: string[] };

/**
 * Checks an untrusted request body against the widget rules. On failure `details` is always
 * non-empty and reports every problem found, not just the first.
 */
export function validateWidgetInput(payload: unknown): Validation {
    if (typeof payload !== "object" || payload === null || Array.isArray(payload)) {
        return { ok: false, details: ["request body must be a JSON object with name and quantity"] };
    }
    const { name, quantity } = payload as Record<string, unknown>;
    const details: string[] = [];

    let validName: string | undefined;
    if (name === undefined) {
        details.push("name is required");
    } else if (typeof name !== "string") {
        details.push("name must be a string");
    } else {
        const trimmed = name.trim();
        if (trimmed.length === 0) details.push("name must not be empty");
        else if (trimmed.length > NAME_MAX_LENGTH) details.push(`name must be at most ${NAME_MAX_LENGTH} characters`);
        else validName = trimmed;
    }

    let validQuantity: number | undefined;
    if (quantity === undefined) {
        details.push("quantity is required");
    } else if (typeof quantity !== "number" || !Number.isInteger(quantity)) {
        details.push("quantity must be an integer");
    } else if (quantity < 0) {
        details.push("quantity must be greater than or equal to 0");
    } else {
        validQuantity = quantity;
    }

    if (validName === undefined || validQuantity === undefined) return { ok: false, details };
    return { ok: true, value: { name: validName, quantity: validQuantity } };
}

export class WidgetStore {
    private readonly widgets = new Map<string, Widget>();

    /** All widgets, oldest first. Returns copies, so callers cannot mutate the store. */
    list(): Widget[] {
        return [...this.widgets.values()].map((widget) => ({ ...widget }));
    }

    get(id: string): Widget | undefined {
        const widget = this.widgets.get(id);
        return widget === undefined ? undefined : { ...widget };
    }

    /** Stores a widget for input that has already passed {@link validateWidgetInput}. */
    create(input: WidgetInput): Widget {
        const widget: Widget = {
            id: randomUUID(),
            name: input.name,
            quantity: input.quantity,
            createdAt: new Date().toISOString(),
        };
        this.widgets.set(widget.id, widget);
        return { ...widget };
    }

    /** Returns true when a widget was removed, false when the id was unknown. */
    delete(id: string): boolean {
        return this.widgets.delete(id);
    }

    clear(): void {
        this.widgets.clear();
    }
}
